from .core import BASE, SITE, UPDATED, breadcrumb, faq, page, quick_answer, takeaways


def build():
    path='/en/labs/instruction-conflict/'
    target=SITE/'en/labs/instruction-conflict'
    target.mkdir(parents=True,exist_ok=True)
    title='Instruction Conflict Lab — Prompt authority and boundaries | AhaFrame'
    desc='Debug a simulated support-agent prompt by separating instruction authority, retrieved context, output contracts, and the runtime controls that prompts cannot enforce.'
    schema={
        '@context':'https://schema.org',
        '@graph':[
            {'@type':'WebPage','@id':BASE+path+'#webpage','url':BASE+path,'name':'Instruction Conflict Lab','description':desc,'inLanguage':'en','dateModified':UPDATED,'mainEntity':{'@id':BASE+path+'#learning-resource'}},
            {'@type':'LearningResource','@id':BASE+path+'#learning-resource','name':'Instruction Conflict Lab','description':desc,'url':BASE+path,'inLanguage':'en','educationalLevel':'Intermediate','learningResourceType':'Interactive simulation','timeRequired':'PT22M','isAccessibleForFree':True,'publisher':{'@id':BASE+'/#organization'}},
        ],
    }
    body=f'''<div class="container"><div class="breadcrumb"><a href="/en/">Home</a> / Production Labs / Instruction Conflict Lab</div><section class="lesson-hero"><div class="lesson-title-row"><div class="lesson-icon">¶</div><div><h1>Instruction Conflict Lab</h1><div class="badges"><span class="badge level">Production Lab Preview</span><span class="badge">Prompt Engineering</span><span class="badge">22 min</span></div><p class="lede">A refund-capable support agent receives system instructions, developer instructions, retrieved policy text, and a user request that all sound actionable. Your job is to fix the Prompt layer—and then notice what Prompt still cannot enforce.</p></div></div><div class="lesson-tools"><button type="button" class="btn small" data-share>Share</button></div></section>{quick_answer('Prompt Engineering defines behavioral instructions and authority, but it cannot replace reliable context assembly, tool permissions, runtime safeguards, or release evaluation.')}
    <div data-instruction-conflict-lab><section class="card interactive"><div class="panel-title"><span>Broken instruction contract</span><span class="badge">Deterministic simulation</span></div><p class="subtle">The baseline treats instruction-like text too uniformly. Retrieved evidence can act like an instruction, the highest-authority safety rule is vague, and the output contract is loose.</p><div class="lab-control-grid" style="display:grid;grid-template-columns:1fr 1fr;gap:24px;margin-top:18px"><div><label class="label" for="instruction-authority">Authority model</label><select id="instruction-authority" class="select" style="margin-top:8px"><option value="flat">Flat / last instruction wins</option><option value="hierarchical">Source-aware hierarchy</option></select><label class="label" for="instruction-specificity" style="display:block;margin-top:18px">System safety rule</label><select id="instruction-specificity" class="select" style="margin-top:8px"><option value="vague">Vague</option><option value="explicit">Explicit approval boundary</option></select><label class="label" for="instruction-retrieval-mode" style="display:block;margin-top:18px">Retrieved policy treatment</label><select id="instruction-retrieval-mode" class="select" style="margin-top:8px"><option value="instructional">May act like instruction</option><option value="data-only">Evidence only</option></select></div><div><label class="label" for="instruction-schema">Output contract</label><select id="instruction-schema" class="select" style="margin-top:8px"><option value="loose">Free-form recommendation</option><option value="strict">Typed decision schema</option></select><label class="label" for="instruction-ambiguity" style="display:block;margin-top:18px">Policy ambiguity</label><select id="instruction-ambiguity" class="select" style="margin-top:8px"><option value="high">High</option><option value="resolved">Resolved</option></select><div class="note" style="margin-top:16px"><strong>Cross-layer constraint:</strong> the refund tool itself is still capable of direct execution. This Lab lets you repair Prompt authority, but it intentionally does not let Prompt become a permission system.</div><div class="actions" style="margin-top:16px"><button type="button" class="btn primary" data-instruction-preset>Apply prompt-layer fix</button><button type="button" class="btn" data-instruction-reset>Reset broken baseline</button></div></div></div></section>
    <section class="card lesson-section" style="padding:20px;margin-top:18px"><div class="panel-title"><span>Prompt outcome</span><strong data-instruction-state-label>PROMPT FAILURE</strong></div><div class="metrics" style="margin-top:14px"><div class="metric">Instruction adherence<br><strong data-instruction-adherence>—</strong></div><div class="metric">Ambiguity risk<br><strong data-instruction-ambiguity-risk>—</strong></div><div class="metric">Policy violation risk<br><strong data-instruction-policy-risk>—</strong></div><div class="metric">Output validity<br><strong data-instruction-validity>—</strong></div><div class="metric">Prompt quality<br><strong data-instruction-prompt-quality>—</strong></div><div class="metric">Unresolved conflicts<br><strong data-instruction-conflict-count>—</strong></div><div class="metric">Harness risk<br><strong data-instruction-harness-risk>—</strong></div><div class="metric">Release evidence<br><strong data-instruction-release-evidence>—</strong></div></div><div class="note" style="margin-top:14px"><strong>Current diagnosis:</strong> <span data-instruction-diagnosis>Calculating…</span><br><strong>Inspect next:</strong> <span data-instruction-next-layer>—</span></div></section>
    <section class="card lesson-section" style="padding:20px;margin-top:18px"><div class="panel-title"><span>Instruction and context sources</span><span class="badge">Same text can have different authority</span></div><p class="subtle">The important distinction is not whether a sentence sounds imperative. The application must decide which sources define behavior, which sources provide evidence, and which capabilities are enforced outside the prompt.</p><div class="takeaways" data-instruction-source-stack style="margin-top:12px"></div></section>
    <section class="card lesson-section" style="padding:20px;margin-top:18px"><div class="panel-title">Prompt repair vs. system repair</div><div class="compare-grid" style="margin-top:14px"><div class="compare-card warn"><span class="label">Broken baseline</span><strong>Instruction sources blur together</strong><p class="subtle">The model can over-trust retrieved text or the user's request because authority and policy are underspecified.</p></div><span class="flow-arrow">→</span><div class="compare-card good"><span class="label">Your current Prompt layer</span><div data-instruction-compare style="display:grid;gap:6px;margin-top:6px"><span>Waiting for changes…</span></div></div></div></section></div>
    {takeaways([('Authority is part of the prompt contract','System-owned instructions, developer instructions, retrieved evidence, and user input should not be treated as interchangeable sources.'),('Context can look like an instruction without becoming one','Retrieved text may contain imperative language, but its role is evidence unless the application deliberately grants it authority.'),('Structured output reduces ambiguity, not capability','A typed decision can make downstream behavior easier to validate, but it does not enforce what a tool is allowed to do.'),('Prompt cannot become a permission boundary','If an irreversible tool must require approval, enforce that constraint in the Harness rather than hoping the model always remembers the sentence.'),('Prompt quality is not release evidence','Even a coherent instruction contract still needs representative Evaluation before a production release decision is justified.')])}
    <section class="card section-explainer"><span class="eyebrow">Prompt Engineering</span><h2>Why is instruction hierarchy more important than adding more prompt text?</h2><p>Production prompts combine multiple sources: application-owned policy, developer guidance, user input, retrieved documents, tool descriptions, memory, and output schemas. The model sees text, but the engineering system assigns responsibility. If the application allows every instruction-like sentence to compete equally, adding more wording can increase ambiguity instead of control.</p><h3>Prompt and Context solve different problems</h3><p>Prompt Engineering asks what behavior the model should follow. Context Engineering asks what information the model should know now. A retrieved refund policy can contain phrases such as “approve up to $500,” but retrieval does not automatically make that phrase a higher-authority instruction. Treating evidence as executable policy creates a boundary failure between Prompt and Context.</p><h3>Specificity matters when consequences differ</h3><p>“Follow the policy” is weaker than an explicit operational constraint such as “refunds above $100 require human approval.” Clear constraints improve the probability that the model selects the intended action. They are especially valuable when the developer instruction emphasizes speed or customer satisfaction and the user asks the model to bypass a safeguard.</p><h3>Why does strict output help?</h3><p>A typed output such as `APPROVE`, `REQUEST_APPROVAL`, or `DECLINE` reduces ambiguity for downstream code and makes validation easier. It does not make the system safe by itself. If the runtime exposes a direct refund tool without enforcing approval, a malformed call, a future model regression, or another path can still bypass the desired behavior.</p><h3>Where does Prompt Engineering stop?</h3><p>Once the instruction contract is coherent, remaining risks should move to the correct layer. Missing evidence is a Context problem. Unsafe capability exposure, tool permissions, approval enforcement, timeouts, and validation are Harness problems. Whether the combined system is safe enough to ship is an Evaluation problem. AhaFrame intentionally leaves those responsibilities visible instead of pretending the perfect prompt eliminates them.</p><h3>What is simulated here?</h3><p>All adherence, ambiguity, policy-risk, output-validity, and harness-risk values are deterministic educational scores. No live model is being prompted and no real refund system is connected. Production prompt behavior must be tested against representative tasks, real models, actual tool boundaries, and validated evaluation criteria.</p><h3>Common questions</h3>{faq([('Is retrieved text always untrusted?','It should be treated according to its application-defined role. Retrieved documents can be valuable evidence without being granted authority to override application-owned instructions.'),('Can a strong system prompt replace tool permissions?','No. A prompt influences model behavior; permissions and approval enforcement belong in the runtime or Harness.'),('Does structured output solve prompt injection?','No. It narrows the output contract and helps validation, but source authority, context isolation, permissions, and evaluation still matter.'),('Why not simply make the system prompt longer?','Length is not the objective. The goal is a clear authority model, explicit consequential constraints, and a contract that downstream systems can verify.')])}<div class="references"><strong>AhaFrame simulation note</strong> · Reviewed {UPDATED}. Values are synthetic and designed to teach engineering boundaries, not universal prompt-quality thresholds.</div></section>
    <section class="card build-card"><div><span class="eyebrow">Build challenge</span><h3>Draw the boundary between instruction, evidence, and enforcement.</h3><p>For a refund-capable agent, identify which rules belong in the Prompt, which facts belong in Context, which actions must be enforced by the Harness, and what Evaluation evidence would be required before release.</p></div><a class="btn" data-event="instruction_conflict_build_challenge_started" href="/en/early-access/?intent=instruction-conflict-build-challenge">Take the challenge →</a></section>
    <section class="card next-band"><div><strong>You repaired behavior without pretending the system is finished.</strong><div class="subtle">Next, Graph Engineering will show how tools, deterministic steps, agents, branches, joins, and human gates become an explicit workflow topology.</div></div><a class="btn primary" data-event="instruction_conflict_next_layer_click" href="/en/early-access/?intent=agent-workflow-graph-lab">Continue to Graph Engineering →</a></section></div>'''
    scripts='<script src="/assets/instruction-conflict-scenario.js" defer></script><script src="/assets/prompt-authority.js" defer></script>'
    (target/'index.html').write_text(page(title,desc,path,body,active='Lessons',schemas=[schema,breadcrumb([('AhaFrame','/en/'),('Production Labs','/en/#production-labs'),('Instruction Conflict Lab',path)])],scripts=scripts),encoding='utf-8')
